# run-all.ps1 -- Orchestrate the full desktop E2E test suite (Windows).
#
# Runs wait-for-mount, FUSE file I/O tests, and API round-trip tests.
# Reports an aggregate pass/fail summary and exits with the total failure count.
#
# Environment:
#   MOUNT_POINT   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   API_URL       Backend API URL (default: http://localhost:3000)
#   TEST_SECRET   test-login shared secret (default: e2e-test-secret-ci-only)

$ErrorActionPreference = "Stop"

$MountPoint = if ($env:MOUNT_POINT) { $env:MOUNT_POINT } else { "$env:USERPROFILE\CipherBox" }
$ApiUrl = if ($env:API_URL) { $env:API_URL } else { "http://localhost:3000" }
$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$TotalFail = 0

Write-Host "============================================"
Write-Host "  CipherBox Desktop E2E Test Suite"
Write-Host "============================================"
Write-Host ""
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host ""

# ---- Step 1: Wait for mount ----
Write-Host "--- Step 1: Wait for mount ---"
try {
    & "$PSScriptRoot\wait-for-mount.ps1" -MountPoint $MountPoint
} catch {
    Write-Host "FATAL: Mount not available. Cannot continue."
    exit 1
}
Write-Host ""

# ---- Step 2: FUSE file operations ----
Write-Host "--- Step 2: FUSE file operations ---"
$FuseExitCode = 0
try {
    & "$PSScriptRoot\test-fuse-operations.ps1" -MountPoint $MountPoint
    $FuseExitCode = $LASTEXITCODE
} catch {
    $FuseExitCode = 1
}

if ($FuseExitCode -eq 0) {
    Write-Host "FUSE operations: ALL PASSED"
} else {
    Write-Host "FUSE operations: $FuseExitCode FAILURE(S)"
    $TotalFail += $FuseExitCode
}
Write-Host ""

# ---- Step 3: API round-trip ----
Write-Host "--- Step 3: API round-trip ---"
$RtExitCode = 0
try {
    & "$PSScriptRoot\test-round-trip.ps1" -MountPoint $MountPoint -ApiUrl $ApiUrl -TestSecret $TestSecret
    $RtExitCode = $LASTEXITCODE
} catch {
    $RtExitCode = 1
}

if ($RtExitCode -eq 0) {
    Write-Host "API round-trip: ALL PASSED"
} else {
    Write-Host "API round-trip: $RtExitCode FAILURE(S)"
    $TotalFail += $RtExitCode
}
Write-Host ""

# ---- Summary ----
Write-Host "============================================"
Write-Host "  Summary"
Write-Host "============================================"
Write-Host "  Total failures: $TotalFail"
Write-Host "============================================"

exit $TotalFail

# test-fuse-operations.ps1 -- Exercise FUSE mount file I/O operations (Windows).
#
# Usage: .\test-fuse-operations.ps1 [-MountPoint <path>]
#   -MountPoint  Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#
# Tests: create, read, overwrite, mkdir, nested write, binary round-trip,
#        rename, delete file, delete directory.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox"
)

$ErrorActionPreference = "Continue"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== FUSE File I/O Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host ""

# ---- Test 1: Create and read text file ----
Write-Host "--- Test 1: Create and read text file ---"
Set-Content -Path "$MountPoint\e2e-test.txt" -Value "Hello from CI" -NoNewline
Start-Sleep -Seconds 3
$Content = Get-Content -Path "$MountPoint\e2e-test.txt" -Raw
if ($Content.Trim() -eq "Hello from CI") {
    Test-Pass "Create and read text file"
} else {
    Test-Fail "Create and read text file (got: '$Content')"
}

# ---- Test 2: Create directory ----
Write-Host "--- Test 2: Create directory ---"
New-Item -ItemType Directory -Path "$MountPoint\e2e-folder" -Force | Out-Null
if (Test-Path "$MountPoint\e2e-folder" -PathType Container) {
    Test-Pass "Create directory"
} else {
    Test-Fail "Create directory"
}

# ---- Test 3: Write file in subdirectory ----
Write-Host "--- Test 3: Write file in subdirectory ---"
Set-Content -Path "$MountPoint\e2e-folder\nested.txt" -Value "Nested content" -NoNewline
Start-Sleep -Seconds 3
$Nested = Get-Content -Path "$MountPoint\e2e-folder\nested.txt" -Raw
if ($Nested.Trim() -eq "Nested content") {
    Test-Pass "Write file in subdirectory"
} else {
    Test-Fail "Write file in subdirectory (got: '$Nested')"
}

# ---- Test 4: Overwrite file (modify) ----
Write-Host "--- Test 4: Overwrite file ---"
Set-Content -Path "$MountPoint\e2e-test.txt" -Value "Modified content" -NoNewline
Start-Sleep -Seconds 3
$Modified = Get-Content -Path "$MountPoint\e2e-test.txt" -Raw
if ($Modified.Trim() -eq "Modified content") {
    Test-Pass "Overwrite file"
} else {
    Test-Fail "Overwrite file (got: '$Modified')"
}

# ---- Test 5: Binary file round-trip ----
Write-Host "--- Test 5: Binary file round-trip ---"
$TempBinary = "$env:TEMP\e2e-binary.bin"
$MountBinary = "$MountPoint\e2e-binary.bin"
$Bytes = New-Object byte[] (256 * 1024)
[System.Security.Cryptography.RandomNumberGenerator]::Fill($Bytes)
[System.IO.File]::WriteAllBytes($TempBinary, $Bytes)
Copy-Item -Path $TempBinary -Destination $MountBinary
Start-Sleep -Seconds 5
$HashOrig = (Get-FileHash -Path $TempBinary -Algorithm SHA256).Hash
$HashMount = (Get-FileHash -Path $MountBinary -Algorithm SHA256).Hash
if ($HashOrig -eq $HashMount) {
    Test-Pass "Binary file round-trip (256KB)"
} else {
    Test-Fail "Binary file round-trip (orig: $HashOrig, mount: $HashMount)"
}

# ---- Test 6: Rename file ----
Write-Host "--- Test 6: Rename file ---"
Move-Item -Path "$MountPoint\e2e-test.txt" -Destination "$MountPoint\e2e-renamed.txt" -Force
Start-Sleep -Seconds 2
$OldExists = Test-Path "$MountPoint\e2e-test.txt"
$NewExists = Test-Path "$MountPoint\e2e-renamed.txt"
if (-not $OldExists -and $NewExists) {
    $Renamed = Get-Content -Path "$MountPoint\e2e-renamed.txt" -Raw
    if ($Renamed.Trim() -eq "Modified content") {
        Test-Pass "Rename file"
    } else {
        Test-Fail "Rename file (content changed: '$Renamed')"
    }
} else {
    Test-Fail "Rename file (old exists: $OldExists, new exists: $NewExists)"
}

# ---- Test 7: Delete file ----
Write-Host "--- Test 7: Delete file ---"
Remove-Item -Path "$MountPoint\e2e-renamed.txt" -Force
Start-Sleep -Seconds 2
if (-not (Test-Path "$MountPoint\e2e-renamed.txt")) {
    Test-Pass "Delete file"
} else {
    Test-Fail "Delete file (still exists)"
}

# ---- Test 8: Delete directory ----
Write-Host "--- Test 8: Delete directory ---"
Remove-Item -Path "$MountPoint\e2e-folder" -Recurse -Force
Start-Sleep -Seconds 2
if (-not (Test-Path "$MountPoint\e2e-folder")) {
    Test-Pass "Delete directory"
} else {
    Test-Fail "Delete directory (still exists)"
}

# ---- Test 9: Cleanup ----
Write-Host "--- Test 9: Cleanup ---"
Remove-Item -Path $MountBinary -Force -ErrorAction SilentlyContinue
Remove-Item -Path $TempBinary -Force -ErrorAction SilentlyContinue
Test-Pass "Cleanup"

# ---- Summary ----
Write-Host ""
Write-Host "=== FUSE File I/O Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "=============================="

exit $Fail

# test-round-trip.ps1 -- Verify desktop FUSE writes are visible via the API (Windows).
#
# Usage: .\test-round-trip.ps1 [-MountPoint <path>] [-ApiUrl <url>] [-TestSecret <secret>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#   -TestSecret   Shared secret for test-login (default: e2e-test-secret-ci-only)
#
# The server is zero-knowledge -- it cannot decrypt file contents.
# These tests prove the pipeline: FUSE write -> encrypt -> IPFS upload -> IPNS publish -> API visibility.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000",
    [string]$TestSecret = "e2e-test-secret-ci-only"
)

$ErrorActionPreference = "Continue"

$TestEmail = "e2e-desktop-rt-$([DateTimeOffset]::UtcNow.ToUnixTimeSeconds())@test.local"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== API Round-Trip Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host ""

# ---- Test 1: Authenticate via test-login ----
Write-Host "--- Test 1: Authenticate via test-login ---"
$Body = @{
    email  = $TestEmail
    secret = $TestSecret
} | ConvertTo-Json

try {
    $AuthResponse = Invoke-RestMethod -Uri "$ApiUrl/auth/test-login" `
        -Method Post `
        -ContentType "application/json" `
        -Body $Body

    $AccessToken = $AuthResponse.accessToken
    if ($AccessToken) {
        Test-Pass "Authenticate via test-login"
    } else {
        Test-Fail "Authenticate via test-login (no accessToken in response)"
        Write-Host "FATAL: Cannot proceed without authentication."
        Write-Host ""
        Write-Host "=== API Round-Trip Results ==="
        Write-Host "  Passed: $Pass"
        Write-Host "  Failed: $Fail"
        Write-Host "==============================="
        exit $Fail
    }
} catch {
    Test-Fail "Authenticate via test-login ($_)"
    Write-Host "FATAL: Cannot proceed without authentication."
    Write-Host ""
    Write-Host "=== API Round-Trip Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "==============================="
    exit $Fail
}

$Headers = @{ Authorization = "Bearer $AccessToken" }

# ---- Test 2: Desktop writes file, API verifies vault exists ----
Write-Host "--- Test 2: Verify vault has content after FUSE write ---"
Set-Content -Path "$MountPoint\rt-test.txt" -Value "API-visible content" -NoNewline
Start-Sleep -Seconds 5

try {
    $VaultResponse = Invoke-RestMethod -Uri "$ApiUrl/vault" `
        -Headers $Headers

    $RootIpns = $VaultResponse.rootIpnsName
    if ($RootIpns) {
        Test-Pass "Vault has rootIpnsName after FUSE write ($RootIpns)"
    } else {
        Test-Fail "Vault has no rootIpnsName"
    }
} catch {
    Test-Fail "Vault API call failed ($_)"
    $RootIpns = $null
}

# ---- Test 3: Verify IPNS resolve returns data ----
Write-Host "--- Test 3: Verify IPNS resolve returns CID ---"
if ($RootIpns) {
    try {
        $IpnsResponse = Invoke-RestMethod -Uri "$ApiUrl/ipns/$RootIpns/resolve" `
            -Headers $Headers

        $ResolvedCid = $IpnsResponse.cid
        if (-not $ResolvedCid) { $ResolvedCid = $IpnsResponse.value }

        if ($ResolvedCid) {
            Test-Pass "IPNS resolve returned CID ($ResolvedCid)"
        } else {
            Test-Fail "IPNS resolve did not return expected CID"
        }
    } catch {
        Test-Fail "IPNS resolve failed ($_)"
    }
} else {
    Test-Fail "IPNS resolve skipped (no rootIpnsName)"
}

# ---- Cleanup ----
Write-Host "--- Cleanup ---"
Remove-Item -Path "$MountPoint\rt-test.txt" -Force -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2

# ---- Summary ----
Write-Host ""
Write-Host "=== API Round-Trip Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "==============================="

exit $Fail

